import {ArrowGraphHashed} from '@rimbu/graph';
type Id = string & {readonly __id:unique symbol}; declare const a:Id; declare const b:Id;
const g = ArrowGraphHashed.empty<Id>().connect(a,b);
const ids:Iterable<Id> = g.streamNodes();
// @ts-expect-error Plain string must not enter the branded graph.
g.addNode('plain');

import * as G from 'effect/Graph';
type Id = string & {readonly __id:unique symbol}; declare const a:Id;
const g = G.directed<Id,{kind:'supports'}>(m => {G.addNode(m,a);});
g.nodes.set(123,a); // Accepted mutation through the publicly immutable Graph.
const node:G.NodeIndex = 0; const edge:G.EdgeIndex = node; // Both aliases of number.

import * as G from 'effect4/Graph';
type Id = string & {readonly __id: unique symbol}; declare const a: Id;
const g = G.directed<Id, {kind:'supports'}>(m => { G.addNode(m,a); });
const ids: Iterable<Id> = G.values(G.nodes(g));
// @ts-expect-error Graph storage is hidden from the public interface.
g.nodes.set(1,a);
const mut = G.beginMutation(g);
// @ts-expect-error MutableGraph must not be widened to a different node domain.
const broad: G.MutableDirectedGraph<string,{kind:'supports'}> = mut;

