import type {IGraph} from '@thi.ng/adjacency';
declare const g:IGraph<string>;
const actual:Iterable<number> = g.neighbors('id');
// @ts-expect-error The actual declaration returns numeric neighbours even for IGraph<string>.
const wanted:Iterable<string> = g.neighbors('id');
